mapper.select:
SELECT custom_role_id, tenant_id, role_name, status, version, created_at, disabled_at
FROM organization_access.tenant_custom_role
WHERE tenant_id = #{tenantId}
  AND custom_role_id = #{customRoleId}
  AND status = 'ACTIVE'
FOR UPDATE

mapper.update:
UPDATE organization_access.tenant_custom_role
SET status = #{status},
    version = #{version},
    disabled_at = #{disabledAt}
WHERE tenant_id = #{tenantId}
  AND custom_role_id = #{customRoleId}

UPDATE organization_access.tenant_membership
SET permission_version = #{permissionVersion},
    version = #{version},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND membership_id = #{membershipId}
